export function isKerisiRemainingRegistered(menuId: number): boolean {
  return Object.prototype.hasOwnProperty.call(KERISI_REMAINING_REGISTRY, menuId);
}

export function getKerisiRemainingSpec(menuId: number): KerisiRemainingPageSpec | null {
  return KERISI_REMAINING_REGISTRY[menuId] ?? null;
}
